import{_ as a,o,c as t,a5 as r}from"./chunks/framework.DOB-AMqW.js";const u=JSON.parse('{"title":"Stillora Privacy Policy","description":"Official Privacy Policy for the Stillora application.","frontmatter":{"title":"Stillora Privacy Policy","description":"Official Privacy Policy for the Stillora application.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/stillora.md","filePath":"privacy/stillora.md"}'),i={name:"privacy/stillora.md"};function n(s,e,l,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy-for-stillora" tabindex="-1">Privacy Policy for Stillora <a class="header-anchor" href="#privacy-policy-for-stillora" aria-label="Permalink to &quot;Privacy Policy for Stillora&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Stillora is an offline-first ambient sound application developed by <strong>Anand Raja</strong>. It does not require an account and does not include advertising, analytics, tracking, crash reporting, or cloud sync.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Stillora stores the settings and content you create within the app, including:</p><ul><li>Theme, volume, timer, sound-transition, and playback preferences</li><li>The last selected sound and background</li><li>Active sound-mix layers and their volume levels</li><li>Saved mix names, selected sounds, and creation dates</li></ul><p>This information is stored locally in the app&#39;s private storage. The developer does not receive it.</p><h2 id="audio-and-video" tabindex="-1">Audio and Video <a class="header-anchor" href="#audio-and-video" aria-label="Permalink to &quot;Audio and Video&quot;">​</a></h2><p>Stillora&#39;s sound and moving-background files are included with the app. They are played locally and are not streamed from a media service.</p><h2 id="backup-and-restore" tabindex="-1">Backup and Restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and Restore&quot;">​</a></h2><p>When you choose <strong>Export backup</strong>, Stillora creates a JSON file containing your local settings and saved mixes. You choose where to save or share that file. When you choose <strong>Import backup</strong>, Stillora reads only the backup file you select. Backup files are not uploaded to the developer.</p><p>You are responsible for protecting exported backup files and deleting copies you no longer need.</p><h2 id="network-requests-and-third-party-services" tabindex="-1">Network Requests and Third-Party Services <a class="header-anchor" href="#network-requests-and-third-party-services" aria-label="Permalink to &quot;Network Requests and Third-Party Services&quot;">​</a></h2><p>Stillora does not use advertising, analytics, or cloud-storage services. Its interface references Google Fonts. When the app can access the internet, the device may request font resources from Google. Google may receive standard connection information such as the device&#39;s IP address, user agent, and request time. Google&#39;s handling of that information is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><p>The core sound, video, timer, mixing, and settings features do not require a network connection.</p><h2 id="device-permissions" tabindex="-1">Device Permissions <a class="header-anchor" href="#device-permissions" aria-label="Permalink to &quot;Device Permissions&quot;">​</a></h2><p>The reviewed source does not use the camera, microphone, location, contacts, phone, SMS, or advertising identifier. Internet access may be available to the Android application for web content such as the Google-hosted font resources described above.</p><h2 id="data-sharing" tabindex="-1">Data Sharing <a class="header-anchor" href="#data-sharing" aria-label="Permalink to &quot;Data Sharing&quot;">​</a></h2><p>Stillora does not sell user information. The developer does not receive or share the settings, sound selections, or mixes stored by the app. Limited technical connection information may be processed by Google when font resources are requested, as described above.</p><p>If you contact the developer by email, the information you include is used only to respond to your request and address related support or privacy matters.</p><h2 id="data-retention-and-deletion" tabindex="-1">Data Retention and Deletion <a class="header-anchor" href="#data-retention-and-deletion" aria-label="Permalink to &quot;Data Retention and Deletion&quot;">​</a></h2><p>Local settings and saved mixes remain on the device until you clear Stillora&#39;s app data or uninstall the app. Exported backup files remain wherever you saved or shared them and must be deleted separately.</p><p>Stillora has no account or developer-operated cloud database, so there is no server-side app account data to request for deletion.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>Stillora does not knowingly collect personal information from children. Because the app has no account system, users should not enter personal or sensitive information in saved mix names.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Stillora&#39;s features or data practices change. The effective and last-updated dates will be revised when changes are published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy questions about Stillora, contact:</p><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',31)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
